-- Running it again will not duplicate tours (it skips existing ones).
-- =====================================================================

insert into public.tours (id, sort, region, length, days, title, summary, season, start_from, img, alt, plan, incl, excl, note) values
('murree', 10, 'Murree & Galiyat', 'short', '2 days', 'Murree Hills and Patriata', 'Mall Road, Kashmir Point and the Patriata chairlift, with a night at our own hotel on The Mall.', 'All year, snow in winter', 'Islamabad or Rawalpindi', 'https://upload.wikimedia.org/wikipedia/commons/thumb/8/8a/Patriatta_%28cropped%29.jpg/960px-Patriatta_%28cropped%29.jpg', 'Patriata cable car cabins above forested hills near Murree', '[["Day 1","Drive from Islamabad (about 1.5 hours). Check in at Al-Maaz Hotel on The Mall. Evening walk along Mall Road, the GPO and Kashmir Point."],["Day 2","Morning at Patriata for the chairlift and cable car. Stop at Pindi Point, then drive back to Islamabad."]]'::jsonb, '["Private car with driver","1 night at Al-Maaz Hotel","Fuel, tolls and parking"]'::jsonb, '["Meals, unless added to your package","Chairlift and cable car tickets"]'::jsonb, null),
('galiyat', 20, 'Murree & Galiyat', 'short', '2 days', 'Galiyat: Ayubia and Nathia Gali', 'Pine forests, the Ayubia chairlift, the Pipeline Track and the ridges of Nathia Gali.', 'All year, snow in winter', 'Murree or Islamabad', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c8/Ayubia%2C_Pakistan.jpg/960px-Ayubia%2C_Pakistan.jpg', 'Forested ridges of Ayubia in the Galiyat', '[["Day 1","From Murree through Changla Gali to Ayubia for the chairlift and the Pipeline Track walk to Dunga Gali. Evening in Nathia Gali."],["Day 2","Morning walk to Mukshpuri or Miranjani viewpoints, then return through Abbottabad or Murree."]]'::jsonb, '["Private vehicle with driver","Fuel, tolls and parking","Hotel stays as agreed in your package","Driver''s meals and stay"]'::jsonb, '["Meals, unless added to your package","Entry tickets and activities","Personal expenses and tips","Ayubia chairlift"]'::jsonb, null),
('hazara', 30, 'Hazara & Kaghan', 'short', '3 days', 'Abbottabad, Balakot and Shogran', 'Abbottabad, Mansehra and Balakot, then Kiwai, Shogran and the Siri Paye meadows.', 'April to November', 'Islamabad', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/ae/Siri_Paye%2C_Shogran%2C_Kaghan_Valley.jpg/960px-Siri_Paye%2C_Shogran%2C_Kaghan_Valley.jpg', 'Siri Paye meadow and pond above Shogran', '[["Day 1","Islamabad to Abbottabad for Shimla Hill, then on through Mansehra to Balakot on the Kunhar River."],["Day 2","Kiwai waterfall, then up to Shogran. Jeep to the Siri Paye meadows."],["Day 3","Morning in Shogran, then back to Islamabad through Mansehra and Abbottabad."]]'::jsonb, '["Private vehicle with driver","Fuel, tolls and parking","Hotel stays as agreed in your package","Driver''s meals and stay"]'::jsonb, '["Meals, unless added to your package","Entry tickets and activities","Personal expenses and tips","Jeep to Siri Paye"]'::jsonb, null),
('naran', 40, 'Hazara & Kaghan', 'short', '4 days', 'Naran, Kaghan and Saif-ul-Malook', 'The Kunhar River valley, Lake Saif-ul-Malook and Babusar Top.', 'Mid May to September', 'Islamabad', 'https://upload.wikimedia.org/wikipedia/commons/thumb/6/60/Lake_Saiful_Malook_naran_05.jpg/960px-Lake_Saiful_Malook_naran_05.jpg', 'Lake Saif-ul-Malook with snowy peaks reflected in the water', '[["Day 1","Drive to Naran through Abbottabad, Mansehra and Balakot along the Kunhar River."],["Day 2","Jeep to Lake Saif-ul-Malook. Afternoon at leisure in Naran."],["Day 3","Lulusar Lake and Babusar Top, when the pass is open."],["Day 4","Return to Islamabad, stopping at Kiwai or Shogran if time allows."]]'::jsonb, '["Private vehicle with driver","Fuel, tolls and parking","Hotel stays as agreed in your package","Driver''s meals and stay"]'::jsonb, '["Meals, unless added to your package","Entry tickets and activities","Personal expenses and tips","Jeep to Saif-ul-Malook"]'::jsonb, 'The road to Naran and upper Kaghan is closed by snow in winter. In those months we suggest Kiwai and Shogran instead.'),
('neelum', 50, 'Kashmir', 'long', '5 days', 'Neelum Valley, Kashmir', 'Riverside villages, Sharda and the meadows of Arang Kel.', 'April to October', 'Islamabad', 'https://upload.wikimedia.org/wikipedia/commons/thumb/a/aa/Neelum_Valley%2C_Azad_Jammu_%26_Kashmir%2C_Pakistan.jpg/960px-Neelum_Valley%2C_Azad_Jammu_%26_Kashmir%2C_Pakistan.jpg', 'Green slopes along the Neelum River', '[["Day 1","Islamabad to Muzaffarabad, then up the valley to Keran."],["Day 2","Continue to Sharda. Visit the Sharda ruins and riverside."],["Day 3","Kel, then the chairlift and walk up to Arang Kel."],["Day 4","Slow drive back down the valley with village stops."],["Day 5","Return to Islamabad."]]'::jsonb, '["Private vehicle with driver","Fuel, tolls and parking","Hotel stays as agreed in your package","Driver''s meals and stay"]'::jsonb, '["Meals, unless added to your package","Entry tickets and activities","Personal expenses and tips","Arang Kel chairlift"]'::jsonb, 'Foreign nationals may need extra permission for parts of Neelum. Tell us your nationality when you enquire.'),
('swat', 60, 'Swat', 'short', '4 days', 'Swat Valley and Kalam', 'Malam Jabba, the Ushu forest and Mahodand Lake above Kalam.', 'April to October, Malam Jabba also in winter', 'Islamabad', 'https://upload.wikimedia.org/wikipedia/commons/thumb/d/da/Kalam%2C_Swat_%28Pakistan%29.jpg/960px-Kalam%2C_Swat_%28Pakistan%29.jpg', 'The Swat River running through Kalam', '[["Day 1","Motorway drive to Swat (about 4 hours). Evening in Mingora."],["Day 2","Malam Jabba chairlift and viewpoints."],["Day 3","Kalam, the Ushu forest and a jeep to Mahodand Lake in summer."],["Day 4","Swat Museum and Butkara Stupa, then back to Islamabad."]]'::jsonb, '["Private vehicle with driver","Fuel, tolls and parking","Hotel stays as agreed in your package","Driver''s meals and stay"]'::jsonb, '["Meals, unless added to your package","Entry tickets and activities","Personal expenses and tips","Jeep to Mahodand Lake"]'::jsonb, null),
('skardu', 70, 'Gilgit-Baltistan', 'long', '6 days', 'Skardu and Deosai', 'Kachura lakes, Shigar Fort, the cold desert and the high Deosai plains.', 'June to September', 'Islamabad (by road or flight)', 'https://upload.wikimedia.org/wikipedia/commons/thumb/9/9f/Shangrila_resort_skardu.jpg/960px-Shangrila_resort_skardu.jpg', 'Lower Kachura Lake and Shangrila resort near Skardu', '[["Day 1","Fly or drive to Skardu. Visit Lower Kachura (Shangrila) Lake."],["Day 2","Upper Kachura Lake, Shigar Fort and the Sarfaranga cold desert."],["Day 3","Full day on the Deosai plains and Sheosar Lake, when the road is open."],["Day 4","Day trip to Khaplu Palace."],["Day 5","Satpara Lake and Manthokha waterfall."],["Day 6","Return to Islamabad."]]'::jsonb, '["Private vehicle with driver","Fuel, tolls and parking","Hotel stays as agreed in your package","Driver''s meals and stay"]'::jsonb, '["Meals, unless added to your package","Entry tickets and activities","Personal expenses and tips","Flights, if you choose to fly"]'::jsonb, null),
('hunza', 80, 'Gilgit-Baltistan', 'long', '7 days', 'Hunza and Khunjerab (China border)', 'Baltit and Altit forts, Attabad Lake, the Passu Cones and the China border at Khunjerab Pass.', 'May to October', 'Islamabad', 'https://upload.wikimedia.org/wikipedia/commons/thumb/0/0a/China_Border%2C_Pakistan.jpg/960px-China_Border%2C_Pakistan.jpg', 'The Pakistan and China border gate at Khunjerab Pass', '[["Day 1","Islamabad to Chilas or Naran, depending on the season and road."],["Day 2","Continue on the Karakoram Highway to Hunza. Evening in Karimabad."],["Day 3","Baltit and Altit forts. Sunset at Eagle''s Nest viewpoint."],["Day 4","Attabad Lake, Hussaini suspension bridge and the Passu Cones."],["Day 5","Drive to the Pakistan and China border at Khunjerab Pass, then back to Hunza."],["Day 6","Leave Hunza and drive south to Chilas or Naran."],["Day 7","Return to Islamabad."]]'::jsonb, '["Private vehicle with driver","Fuel, tolls and parking","Hotel stays as agreed in your package","Driver''s meals and stay"]'::jsonb, '["Meals, unless added to your package","Entry tickets and activities","Personal expenses and tips","Khunjerab National Park entry"]'::jsonb, 'Khunjerab Pass is above 4,600 metres and opens only in the warmer months. Bring your CNIC or passport.'),
('fairy', 90, 'Gilgit-Baltistan', 'long', '5 days', 'Fairy Meadows and Nanga Parbat', 'A jeep ride and short trek to meadows facing Nanga Parbat, the world''s ninth highest mountain.', 'June to September', 'Islamabad', 'https://upload.wikimedia.org/wikipedia/commons/thumb/c/c1/Fairy_Meadows%2C_Pakistan.jpg/960px-Fairy_Meadows%2C_Pakistan.jpg', 'Pine forest and meadow at Fairy Meadows below snowy peaks', '[["Day 1","Drive to Chilas."],["Day 2","Jeep from Raikot Bridge to Tatoo, then a 2 to 3 hour walk to Fairy Meadows."],["Day 3","Hike towards Beyal Camp and the Nanga Parbat viewpoint."],["Day 4","Walk and jeep back down. Drive to Chilas or Naran."],["Day 5","Return to Islamabad."]]'::jsonb, '["Private vehicle with driver","Fuel, tolls and parking","Hotel stays as agreed in your package","Driver''s meals and stay","Jeep from Raikot Bridge to Tatoo"]'::jsonb, '["Meals, unless added to your package","Entry tickets and activities","Personal expenses and tips","Porters, if needed"]'::jsonb, null),
('islamabad', 100, 'City tours', 'day', 'Full day', 'Islamabad City Highlights', 'Faisal Mosque, Pakistan Monument, Saidpur Village, Daman-e-Koh and dinner at Monal.', 'All year', 'Your hotel in Islamabad or Rawalpindi', 'https://upload.wikimedia.org/wikipedia/commons/thumb/e/e0/Ali_Mujtaba_WLM2017_FAISAL_MOSQUE_019.jpg/960px-Ali_Mujtaba_WLM2017_FAISAL_MOSQUE_019.jpg', 'Faisal Mosque with the Margalla Hills behind', '[["Morning","Faisal Mosque, then the Pakistan Monument and its museum."],["Midday","Lok Virsa heritage museum. Lunch or hi-tea buffet at Ramada by Wyndham if you like."],["Afternoon","Saidpur Village and Daman-e-Koh viewpoint."],["Evening","Dinner at Monal."]]'::jsonb, '["Private car with driver for the day","Fuel and parking"]'::jsonb, '["Meals, unless added to your package","Entry tickets"]'::jsonb, null),
('lahore', 110, 'City tours', 'day', 'Full day', 'Lahore Heritage and Food', 'Lahore Fort, Badshahi Mosque and the Walled City, ending with dinner on Food Street.', 'October to March', 'Your hotel in Lahore', 'https://upload.wikimedia.org/wikipedia/commons/thumb/4/4f/Lahore_Fort_view_from_Baradari.jpg/960px-Lahore_Fort_view_from_Baradari.jpg', 'Alamgiri Gate and gardens of Lahore Fort', '[["Morning","Lahore Fort and Badshahi Mosque."],["Midday","Walk through the Walled City from Delhi Gate to Wazir Khan Mosque."],["Afternoon","Optional Wagah border ceremony."],["Evening","Dinner on Fort Road Food Street, facing the mosque."]]'::jsonb, '["Private car with driver for the day","Fuel and parking"]'::jsonb, '["Meals, unless added to your package","Entry tickets"]'::jsonb, null)
on conflict (id) do nothing;

insert into public.hotels (sort, name, details, icon)
select * from (values
  (10, 'Al-Maaz Hotel', 'The Mall, Murree. Our own hotel', 'star'),
  (20, 'Hotel Felton', 'Bank Road, Murree. Partner hotel', 'buildings'),
  (30, 'Ramada by Wyndham Murree', 'Lower Topa. Rooms and group bookings', 'buildings'),
  (40, 'Mövenpick Centaurus', 'Islamabad. Rooms and group bookings', 'buildings'),
  (50, 'Galiyat and Kaghan', 'Partner hotels in Ayubia, Nathia Gali, Shogran and Naran', 'tree-evergreen')
) as v(sort, name, details, icon)
where not exists (select 1 from public.hotels);

insert into public.venues (sort, name, details)
select * from (values
  (10, 'Ramada by Wyndham, Islamabad', 'Breakfast, hi-tea, lunch and dinner buffets'),
  (20, 'Usmania Restaurant, Murree', 'Buffets and group lunches and dinners'),
  (30, 'Dervash Restaurant, Murree', 'Our own restaurant on The Mall, with family seating and group bookings'),
  (40, 'Galiyat and Kaghan', 'Group dinners in Nathia Gali, Ayubia, Shogran and Naran')
) as v(sort, name, details)
where not exists (select 1 from public.venues);

insert into public.offers (sort, title, body)
select * from (values
  (10, 'Special discount offers', 'Ask about our current company discounts for families, school and college groups and large group bookings. Offers change with the season and are shared with you personally.')
) as v(sort, title, body)
where not exists (select 1 from public.offers);
